(function(){document.addEventListener("DOMContentLoaded",()=>{const t=document.createElement("div");t.id="navControls",t.innerHTML=`
            <button class="nav-btn" id="navBack" title="Back">&#8592;</button>
            <button class="nav-btn" id="navForward" title="Forward">&#8594;</button>
        `,document.body.appendChild(t),document.getElementById("navBack").onclick=()=>{history.length>1&&history.back()},document.getElementById("navForward").onclick=()=>{history.forward()}});let e=0,o=0;document.addEventListener("touchstart",t=>{e=t.touches[0].clientX,o=t.touches[0].clientY},{passive:!0}),document.addEventListener("touchend",t=>{const a=t.changedTouches[0].clientX,c=t.changedTouches[0].clientY,n=a-e,d=c-o;Math.abs(n)<80||Math.abs(n)<Math.abs(d)||(n>0?history.length>1&&history.back():history.forward())},{passive:!0})})();
